export function kmzDocuments(bytes){if(bytes.length>MAX_FILE)throw fail('文件超过25 MB','Fichier supérieur à 25 Mo');if(bytes[0]!==80||bytes[1]!==75)throw fail('KMZ不是有效ZIP压缩包','Archive KMZ invalide');let end=false;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--){if(bytes[i]===80&&bytes[i+1]===75&&bytes[i+2]===5&&bytes[i+3]===6&&i+22+bytes[i+20]+256*bytes[i+21]===bytes.length){end=true;break}}if(!end)throw fail('KMZ压缩包不完整','Archive KMZ incomplète');let docs=[],entries=0,total=0,pending=0,problem=null;const zip=new Unzip(file=>{if(++entries>512)throw fail('压缩包文件过多','Trop de fichiers dans l’archive');if(!/\.kml$/i.test(file.name))return;if(++pending>32)throw fail('KML文件过多','Trop de fichiers KML');if(file.originalSize>MAX_XML)throw fail('KML解压后超过64 MB','KML décompressé supérieur à 64 Mo');let chunks=[],size=0;file.ondata=(err,data,final)=>{if(err){problem=err;return}size+=data.length;total+=data.length;if(size>MAX_XML||total>MAX_TOTAL){file.terminate();throw fail('解压数据超出限制','Limite de décompression dépassée')}chunks.push(data);if(final){let merged=new Uint8Array(size),offset=0;for(let c of chunks){merged.set(c,offset);offset+=c.length}docs.push({name:file.name,text:decode(merged)});pending--}};file.start()});zip.register(UnzipInflate);try{for(let i=0;i<bytes.length;i+=4096){zip.push(bytes.subarray(i,i+4096),i+4096>=bytes.length);if(problem)throw problem}}catch(e){throw fail('KMZ解压失败：'+e.message,'Échec de décompression KMZ')}if(pending||!docs.length)throw fail('KMZ中没有完整KML文件','Aucun fichier KML complet dans le KMZ');return docs}
